source('R/stile.R');source('R/covarianze.R');raw<-read.csv('dati/progetti/co2_weekly.csv');raw$date<-as.Date(raw$date);out<-'risultati/P05';dir.create(out,recursive=TRUE,showWarnings=FALSE)
verifica('serie settimanale conservata',nrow(raw)==2284&&sum(is.na(raw$co2_ppm))==59&&!anyDuplicated(raw$date)&&all(diff(raw$date)==7))
raw$ym<-format(raw$date,'%Y-%m');raw$valido<-as.integer(!is.na(raw$co2_ppm));means<-aggregate(co2_ppm~ym,raw,mean);counts<-aggregate(valido~ym,raw,sum);mo<-merge(counts,means,by='ym',all.x=TRUE);mo$date<-as.Date(paste0(mo$ym,'-01'));mo<-mo[order(mo$date),]
audit<-subset(mo,date>=as.Date('1980-01-01')&date<=as.Date('2000-12-01'));d<-subset(mo,date>=as.Date('1985-01-01')&date<=as.Date('2000-12-01'));verifica('192 mesi con copertura richiesta',nrow(d)==192&&all(d$valido>=3)&&!anyNA(d$co2_ppm))
verifica('aprile 1984 visibile',audit$valido[audit$ym=='1984-04']==1)
d$year<-as.integer(format(d$date,'%Y'));d$month<-as.integer(format(d$date,'%m'));d$t<-d$year+(d$month-.5)/12-1993;d$m<-factor(d$month,levels=1:12)
xs<-scale_x_date(breaks=as.Date(c('1985-01-01','1990-01-01','1995-01-01','2000-01-01')),date_labels='%Y')
salva('P05','F01',ggplot(audit,aes(date,valido))+geom_hline(yintercept=3,colour=geo[2],linetype=2)+geom_point(colour=geo[1],size=1.5)+scale_y_continuous(breaks=1:5)+scale_x_date(breaks=as.Date(c('1980-01-01','1990-01-01','2000-01-01')),date_labels='%Y')+labs(x='Data del mese',y='Settimane valide'))
salva('P05','F02',ggplot(d,aes(date,co2_ppm))+geom_line(colour=geo[1],linewidth=.65)+xs+labs(x='Anno',y='CO₂ mensile (ppm)'))
d$anom<-d$co2_ppm-ave(d$co2_ppm,d$year,FUN=mean)
salva('P05','F03',ggplot(d,aes(month,anom,group=month))+geom_hline(yintercept=0,colour=geo[6],linetype=2)+geom_boxplot(fill=geo[1],alpha=.65,width=.6,outlier.size=1.2)+scale_x_continuous(breaks=c(1,4,7,10,12))+labs(x='Mese',y='Scarto annuo (ppm)'))
fit<-lm(co2_ppm~t+m,d);X<-model.matrix(fit);beta<-unname(coef(fit)[2]);ct<-unname(confint(fit)[2,]);V<-hac_cov(X,resid(fit),12);ch<-intervallo(beta,sqrt(V[2,2]));verifica('rango del modello',qr(X)$rank==13)
d$stima<-fitted(fit);d$residuo<-resid(fit)
salva('P05','F04',ggplot(d,aes(date))+geom_line(aes(y=co2_ppm,colour='Osservata'),linewidth=.65)+geom_line(aes(y=stima,colour='Modello'),linewidth=.65)+scale_colour_manual(values=c(Osservata=geo[1],Modello=geo[2]))+xs+labs(x='Anno',y='CO₂ (ppm)'))
salva('P05','F05',ggplot(d,aes(date,residuo))+geom_hline(yintercept=0,colour=geo[6],linetype=2)+geom_line(colour=geo[1],linewidth=.65)+xs+labs(x='Anno',y='Residuo (ppm)'))
ac<-acf(resid(fit),lag.max=24,plot=FALSE);aa<-data.frame(lag=1:24,acf=as.numeric(ac$acf)[-1]);ref<-1.96/sqrt(192)
salva('P05','F06',ggplot(aa,aes(lag,acf))+geom_hline(yintercept=0,colour=geo[6])+geom_hline(yintercept=c(-ref,ref),colour=geo[2],linetype=2)+geom_segment(aes(xend=lag,yend=0),colour=geo[1],linewidth=.8)+scale_x_continuous(breaks=c(1,6,12,18,24))+scale_y_continuous(labels=fmt)+labs(x='Ritardo (mesi)',y='Autocorrelazione residua'))
sens<-do.call(rbind,lapply(c(0,3,6,12,18,24),function(L){se<-sqrt(hac_cov(X,resid(fit),L)[2,2]);cc<-intervallo(beta,se);data.frame(lag=L,stima=beta,se=se,low=cc[1],high=cc[2])}))
salva('P05','F07',ggplot(sens,aes(lag,stima))+geom_errorbar(aes(ymin=low,ymax=high),width=.8,colour=geo[2],linewidth=.8)+geom_point(colour=geo[1],size=2.8)+scale_x_continuous(breaks=c(0,6,12,18,24))+scale_y_continuous(labels=fmt)+labs(x='Ritardo massimo HAC (mesi)',y='Pendenza (ppm/anno)'))
fq<-lm(co2_ppm~t+m+I(t^2),d);d$curvatura<-fitted(fq)-fitted(fit);bq<-unname(tail(coef(fq),1));d$tasso_locale<-unname(coef(fq)[2])+2*bq*d$t
salva('P05','F08',ggplot(d,aes(date,curvatura))+geom_hline(yintercept=0,colour=geo[6],linetype=2)+geom_line(colour=geo[2],linewidth=.8)+xs+scale_y_continuous(labels=fmt)+labs(x='Anno',y='Differenza (ppm)'))
salva('P05','F09',ggplot(d,aes(date,tasso_locale))+geom_line(colour=geo[2],linewidth=.8)+geom_hline(yintercept=beta,colour=geo[1],linetype=2)+xs+scale_y_continuous(breaks=c(1.4,1.55,1.7),labels=fmt)+labs(x='Anno',y='Tasso locale (ppm/anno)'))
comparison<-data.frame(metodo=c('t i.i.d.','HAC, L = 12'),stima=beta,low=c(ct[1],ch[1]),high=c(ct[2],ch[2]))
salva('P05','F10',ggplot(comparison,aes(stima,metodo))+geom_errorbarh(aes(xmin=low,xmax=high),height=.18,colour=geo[2],linewidth=.85)+geom_point(colour=geo[1],size=3)+scale_x_continuous(breaks=c(1.48,1.54,1.60),labels=fmt,expand=expansion(mult=c(.12,.18)))+labs(x='Pendenza (ppm/anno)',y=NULL))
verifica('anomalia annua centrata',max(abs(tapply(d$anom,d$year,mean)))<1e-10)
write.csv(d,file.path(out,'mensile_modelli.csv'),row.names=FALSE);write.csv(audit,file.path(out,'copertura_1980_2000.csv'),row.names=FALSE);write.csv(sens,file.path(out,'sensibilita_lag.csv'),row.names=FALSE);write.csv(V,file.path(out,'cov_HAC.csv'),row.names=FALSE)
jsonlite::write_json(list(n=192,beta=beta,IC_t=ct,IC_HAC=ch,R2=summary(fit)$r.squared,beta2=bq,max_scarto=max(abs(d$curvatura)),tassi=range(d$tasso_locale),acf=aa,sensibilita=sens),file.path(out,'valori.json'),digits=12,auto_unbox=TRUE,pretty=TRUE)
